// @ts-check
const { test, expect } = require('@playwright/test');
// Keep first-attempt traces for these scroll assertions to expose pre-input actionability movement.
test.use({ trace: 'retain-on-failure' });
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Filters panel keeps what was clicked where it was: opening or closing a filter and choosing or clearing a value
// never scroll the list, also when the chips above it come and go, values elsewhere drop out, or the list gets shorter
// than the scroll position.
const REPOSITORY_ID = uniqueRepositoryId('graph-filter-scroll');
const PEOPLE = 6; // 96 statements: one load draws everyone.
const PROPERTIES = 14;
const property = (index) => `p${String(index + 1).padStart(2, '0')}`;
const DATA = ['@prefix ex: <http://example.org/scroll/> .', '@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .']
    .concat(Array.from({ length: PEOPLE }, (_, person) => `ex:person${person} a ex:Person ; rdfs:label "Person ${person}" ; `
        + Array.from({ length: PROPERTIES }, (_, index) => `ex:${property(index)} "v${(person + index) % 3}"`).join(' ; ')
        + ' .'))
    .join('\n');

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph filter scrolling')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openFilters(page) {
    await page.setViewportSize({ width: 1280, height: 640 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: /Load \d+ statements/ }).click();
    await expect(explorer.locator('.graph-node')).toHaveCount(PEOPLE, { timeout: 30000 });
    await explorer.getByRole('button', { name: /Filter graph nodes/ }).click();
    const panel = explorer.locator('#graph-filter-sidebar');
    await panel.getByRole('button', { name: /more filters/ }).click();
    await expect(panel.locator('.filter-facet summary', { hasText: property(PROPERTIES - 1) })).toHaveCount(1);
    return panel;
}

const facet = (panel, name) => panel.locator('.filter-facet', {
    has: panel.page().locator('summary strong', { hasText: new RegExp(`^${name}$`) })
});

/** Scroll the list of filters to top (a number) or to its end ('end'). */
async function scrollFilters(panel, top) {
    await panel.locator('.filter-facets').evaluate((list, to) => {
        list.scrollTop = to === 'end' ? list.scrollHeight : to;
    }, top);
}

/**
 * Click target and follow where it is on screen for 45 frames after trusted input. Actionability scrolling before
 * pointerdown is outside the measurement; movement after the user input remains covered.
 */
async function clickAndTrack(target, testInfo, label) {
    const handle = await target.elementHandle();
    await handle.evaluate((element) => {
        const list = element.closest('.filter-facets');
        const top = element.getBoundingClientRect().top;
        const record = {
            armed: {
                top,
                listScrollTop: list.scrollTop,
                windowScrollY: window.scrollY,
                time: performance.now(),
            },
            pointerDown: null,
            preInputMovement: null,
            postInputWorst: 0,
            connected: true,
            final: null,
            frames: 0,
        };
        window.__filterScrollTrack = record;
        const onPointerDown = (event) => {
            if (record.pointerDown) return;
            if (!event.isTrusted || !(event.target === element || element.contains(event.target))) return;
            const pointerTop = element.getBoundingClientRect().top;
            record.pointerDown = {
                top: pointerTop,
                listScrollTop: list.scrollTop,
                windowScrollY: window.scrollY,
                time: performance.now(),
                trusted: true,
            };
            record.preInputMovement = Math.abs(pointerTop - record.armed.top);
            requestAnimationFrame(follow);
        };
        document.addEventListener('pointerdown', onPointerDown, { capture: true });
        const follow = () => {
            if (element.isConnected) {
                const currentTop = element.getBoundingClientRect().top;
                record.postInputWorst = Math.max(record.postInputWorst, Math.abs(currentTop - record.pointerDown.top));
                record.final = {
                    top: currentTop,
                    listScrollTop: list.scrollTop,
                    windowScrollY: window.scrollY,
                    time: performance.now(),
                };
            } else {
                record.connected = false;
            }
            if (++record.frames < 45) {
                requestAnimationFrame(follow);
            } else {
                document.removeEventListener('pointerdown', onPointerDown, { capture: true });
            }
        };
    });
    await target.click();
    await target.page().waitForFunction(() => window.__filterScrollTrack.pointerDown?.trusted === true
        && window.__filterScrollTrack.frames >= 45);
    const record = await target.page().evaluate(() => window.__filterScrollTrack);
    await testInfo.attach(`filter-scroll-${label}`, {
        body: JSON.stringify(record, null, 2),
        contentType: 'application/json',
    });
    await handle.dispose();
    return record;
}

test('opening and closing a filter keep its heading where it was clicked', async ({ page }, testInfo) => {
    const panel = await openFilters(page);
    const list = panel.locator('.filter-facets');
    await scrollFilters(panel, 120);
    expect(await list.evaluate((element) => element.scrollTop)).toBeGreaterThan(100);

    const heading = facet(panel, property(6)).locator('summary');
    const headingTrack = await clickAndTrack(heading, testInfo, 'opening-heading');
    expect(headingTrack.pointerDown.trusted).toBe(true);
    expect(headingTrack.frames).toBe(45);
    expect(headingTrack.connected).toBe(true);
    expect(headingTrack.postInputWorst).toBeLessThanOrEqual(1);
    await expect(facet(panel, property(6))).toHaveAttribute('open', '');

    // At the end of the list closing a filter makes the list shorter than the scroll position.
    const last = facet(panel, property(PROPERTIES - 1)).locator('summary');
    await last.click();
    await scrollFilters(panel, 'end');
    const closingTrack = await clickAndTrack(last, testInfo, 'closing-last-heading');
    expect(closingTrack.pointerDown.trusted).toBe(true);
    expect(closingTrack.frames).toBe(45);
    expect(closingTrack.connected).toBe(true);
    expect(closingTrack.postInputWorst).toBeLessThanOrEqual(1);
    await expect(facet(panel, property(PROPERTIES - 1))).not.toHaveAttribute('open', '');
});

test('Playwright actionability scrolling happens before the trusted heading input', async ({ page }, testInfo) => {
    const panel = await openFilters(page);
    const list = panel.locator('.filter-facets');
    await scrollFilters(panel, 0);

    const last = facet(panel, property(PROPERTIES - 1)).locator('summary');
    const armedGeometry = await last.evaluate((element) => {
        const target = element.getBoundingClientRect();
        const viewport = element.closest('.filter-facets').getBoundingClientRect();
        return { targetTop: target.top, viewportBottom: viewport.bottom };
    });
    expect(await list.evaluate((element) => element.scrollTop)).toBe(0);
    expect(armedGeometry.targetTop).toBeGreaterThan(armedGeometry.viewportBottom);

    const track = await clickAndTrack(last, testInfo, 'actionability-scroll');
    expect(track.pointerDown.trusted).toBe(true);
    expect(track.frames).toBe(45);
    expect(track.preInputMovement).toBeGreaterThan(1);
    expect(track.connected).toBe(true);
    expect(track.postInputWorst).toBeLessThanOrEqual(1);
    await expect(facet(panel, property(PROPERTIES - 1))).toHaveAttribute('open', '');
});

test('the trusted-input tracker reports later geometry movement', async ({ page }, testInfo) => {
    await page.setContent('<div class="filter-facets" style="height: 120px; overflow: auto">'
        + '<button id="tracked" type="button">Move after click</button></div>');
    const target = page.locator('#tracked');
    await target.evaluate((element) => {
        element.addEventListener('click', (event) => {
            if (!event.isTrusted) return;
            element.style.transform = 'translateY(20px)';
            element.dataset.testShift = '20px';
        }, { once: true });
    });

    const track = await clickAndTrack(target, testInfo, 'post-input-geometry-shift');
    expect(track.pointerDown.trusted).toBe(true);
    expect(track.frames).toBe(45);
    expect(track.postInputWorst).toBeGreaterThan(1);
    await expect(target).toHaveAttribute('data-test-shift', '20px');
});

test('choosing and clearing a value keep it where it was clicked', async ({ page }, testInfo) => {
    const panel = await openFilters(page);
    // An open filter above the one used loses values that no longer match.
    await facet(panel, property(1)).locator('summary').click();
    await facet(panel, property(5)).locator('summary').click();
    await scrollFilters(panel, 60);

    const value = facet(panel, property(5)).locator('.facet-value', { hasText: 'v0' });
    // The first value chosen adds the chips and the match count above the list.
    const chooseTrack = await clickAndTrack(value, testInfo, 'choosing-value');
    expect(chooseTrack.pointerDown.trusted).toBe(true);
    expect(chooseTrack.frames).toBe(45);
    expect(chooseTrack.connected).toBe(true);
    expect(chooseTrack.postInputWorst).toBeLessThanOrEqual(1);
    await expect(panel.locator('.filter-chips button')).toHaveCount(1);
    await expect(facet(panel, property(1)).locator('.facet-value')).toHaveCount(1);

    // Clearing it takes them away again, near the top of the list.
    const clearTrack = await clickAndTrack(value, testInfo, 'clearing-value');
    expect(clearTrack.pointerDown.trusted).toBe(true);
    expect(clearTrack.frames).toBe(45);
    expect(clearTrack.connected).toBe(true);
    expect(clearTrack.postInputWorst).toBeLessThanOrEqual(1);
    await expect(panel.locator('.filter-chips')).toHaveCount(0);
    await expect(facet(panel, property(1)).locator('.facet-value')).toHaveCount(3);
});
